// Extract error details from the failed node
const inputData = $input.first().json;

const errorMessage = inputData.error?.message || 'Unknown error occurred';
const errorCode = inputData.error?.code || 'UNKNOWN';

return {
  json: {
    status: 'error',
    code: errorCode,
    message: errorMessage,
    timestamp: new Date().toISOString()
  }
};
